(function(){'use strict';const api=SandwormTrace,$=id=>document.getElementById(id);let report=null,revision=0;const status=t=>{$('trace-status').textContent=t;};
function invalidate(){revision++;report=null;$('trace-results').hidden=true;$('trace-tree').replaceChildren();$('trace-review').checked=false;$('trace-export').disabled=true;}
function error(){status('อ่าน trace ไม่สำเร็จ: ตรวจ schema, ID ความสัมพันธ์ และขนาด 1 MiB โดยไม่แสดงข้อมูลต้นฉบับ');}
const money=x=>x===null?'ไม่ครบ':'$'+x.toFixed(6);
function render(){const tid=$('trace-select').value,s=api.summarize(report,tid);$('trace-review').checked=false;$('trace-export').disabled=true;
$('trace-summary').textContent=tid+' · '+s.observations+' ขั้นตอน · '+s.wall_time_ms+' ms wall time · '+s.errors+' error · Generation cost '+money(s.reported_cost_usd)+' (ยอดที่ทราบ '+money(s.known_reported_cost_usd)+') · '+s.unpriced_generations+' generation ไม่มีราคา · '+s.missing_parents+' parent ไม่อยู่ใน export';
const metric=s.scores.filter(x=>x.observation_id===null);$('trace-score-summary').textContent='Trace evaluations: '+(metric.length?metric.map(x=>x.metric_alias+' = '+String(x.value)+' ['+x.data_type+']').join(' · '):'ยังไม่มี')+' · คะแนนที่ไม่รองรับ/อยู่นอก trace '+report.excluded_scores;
$('trace-tree').replaceChildren();function node(r){const d=document.createElement('details');d.className='trace-node';d.open=true;const h=document.createElement('summary');h.textContent=r.type+' / '+r.id+' · '+r.latency_ms+' ms · '+r.status;d.append(h);const t=document.createElement('p');t.textContent='เริ่ม +'+r.start_offset_ms+' ms · Parent '+(r.parent_id||(r.parent_missing?'ไม่ได้อยู่ใน export':'root'))+' · '+(r.model_alias||'ไม่มีโมเดล')+' · Tokens '+(r.input_tokens===null?'ไม่ทราบ':r.input_tokens+' / '+r.output_tokens)+' · Reported '+money(r.reported_cost_usd);d.append(t);const bar=document.createElement('progress');bar.max=Math.max(s.wall_time_ms,1);bar.value=r.latency_ms;bar.setAttribute('aria-label','ระยะเวลา '+r.latency_ms+' ms เทียบกับ trace '+s.wall_time_ms+' ms');d.append(bar);const scores=report.scores.filter(x=>x.observation_id===r.id);if(scores.length){const e=document.createElement('p');e.textContent='Evaluations: '+scores.map(x=>x.metric_alias+' = '+String(x.value)+' ['+x.data_type+']').join(' · ');d.append(e);}for(const child of r.children)d.append(node(child));return d;}for(const r of api.tree(report,tid))$('trace-tree').append(node(r));}
$('trace-input').addEventListener('input',()=>{invalidate();status('ข้อมูลเปลี่ยนแล้ว กรุณาวิเคราะห์ใหม่');});
$('trace-demo').addEventListener('click',()=>{invalidate();$('trace-input').value=JSON.stringify(api.demo,null,2);status('โหลด trace สมมติแล้ว กดดูขั้นตอน Agent');});
$('trace-clear').addEventListener('click',()=>{invalidate();$('trace-input').value='';$('trace-file').value='';status('ล้าง trace จากหน้านี้แล้ว');});
$('trace-analyze').addEventListener('click',()=>{invalidate();try{report=api.parse($('trace-input').value);const opts=[...new Set(report.observations.map(r=>r.trace_id))].map(id=>{const o=document.createElement('option');o.value=id;o.textContent=id;return o;});$('trace-select').replaceChildren(...opts);$('trace-select').value=opts[0].value;render();$('trace-results').hidden=false;status('นำเข้า '+report.observations.length+' ขั้นตอน · '+report.source+' · ไม่ส่งข้อมูลออกเครือข่าย');}catch(_){invalidate();error();}});
$('trace-select').addEventListener('change',()=>{if(!report)return;revision++;render();});
$('trace-file').addEventListener('change',async()=>{const f=$('trace-file').files[0];if(!f)return;invalidate();const rev=revision;try{if(f.size>api.LIMIT||!f.name.endsWith('.json'))throw Error();const text=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());if(rev!==revision)return;api.parse(text);$('trace-input').value=text;status('อ่านไฟล์ในเครื่องแล้ว กดดูขั้นตอน Agent');}catch(_){if(rev===revision)error();}finally{if(rev===revision)$('trace-file').value='';}});
$('trace-review').addEventListener('change',()=>{$('trace-export').disabled=!report||!$('trace-review').checked;});
$('trace-export').addEventListener('click',()=>{if(!report||!$('trace-review').checked)return;const blob=new Blob([JSON.stringify(report,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sandworm-agent-trace.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status('ดาวน์โหลดรายงานที่ผ่าน schema และใช้ alias แล้ว');});
$('trace-to-ledger').addEventListener('click',()=>{if(!report)return;const rows=api.toRuns({...report,observations:report.observations.filter(r=>r.trace_id===$('trace-select').value)});if(!rows.length){status('ไม่มี generation ที่มีโมเดลและ token ครบสำหรับ Ledger');return;}$('run-input').value=JSON.stringify(rows,null,2);$('run-input').dispatchEvent(new Event('input',{bubbles:true}));status('นำ '+rows.length+' generation ที่มี token ครบไปช่อง Run log แล้ว · กำหนด rate card ของ model alias แล้ววิเคราะห์');});
})();
